  function question(){const fields=D.fields.slice(0,state.depth==='quick'?6:14);state.step=Math.max(0,Math.min(state.step,fields.length-1));const f=fields[state.step],value=state.answers[f.key]||'';shell(`<a href="#/choose">← Choose another path</a><section class="discovery-question"><div class="discovery-progress"><span>${state.depth==='quick'?'QUICK MATCH':'DEEPER PROFILE'}</span><strong>Question ${state.step+1} of ${fields.length}</strong></div><progress value="${state.step+1}" max="${fields.length}" aria-label="Questionnaire progress"></progress><form id="discovery-question"><h1>${E(f.title)}</h1>${f.help?`<p>${E(f.help)}</p>`:''}${f.options?`<div class="discovery-options">${f.options.map(([v,l])=>`<label><input type="radio" name="answer" value="${E(v)}" ${value===v?'checked':''}><span>${E(l)}</span></label>`).join('')}</div>`:`<label class="discovery-field"><span>Your answer (optional)</span><textarea name="answer" rows="5" maxlength="2000" placeholder="${E(f.placeholder||'')}">${E(value)}</textarea></label>`}<div class="discovery-actions">${state.step?'<button type="button" class="button btn" data-discovery="back">← Back</button>':''}<button class="primary btn" type="submit">${state.step===fields.length-1?'Show my matches':'Continue'} →</button><button type="button" class="text-link" data-discovery="skip">Skip this question</button></div><small>Saved as you go on this device. Skipping is always okay.</small></form></section>`,'Your journey profile')}
  function results(){const p=Object.fromEntries(new URLSearchParams(location.hash.split('?')[1]||'')),all=config.records(),list=D.search(all,state.answers,p),short=state.shortlist.map(id=>all.find(r=>r.id===id)).filter(Boolean),page=Math.max(1,Number(p.page)||1),items=list.slice((page-1)*12,page*12);const filters=[['season','Season',[['easter','Easter'],['fall','Fall'],['advent','Advent'],['christmas','Christmas'],['summer','Summer']]],['video','Verified video',[['yes','Video available'],['no','Text-only confirmed']]],['experience','Difficulty',[['beginner','Beginner'],['intermediate','Intermediate'],['advanced','Advanced']]],['minutes','Meeting length',[['30','30 minutes'],['45','45 minutes'],['60','60 minutes'],['90','90 minutes']]],['size','Church / group size',D.fields.find(f=>f.key==='size').options],['alignment','Sermon alignment',[['yes','Aligned'],['no','Independent']]],['customization','Available edition',[['ready','Approved ready-made'],['personalize','Personalizable']]]];shell(`<section class="discovery-intro"><span class="eyebrow">YOUR NEXT CHAPTER</span><h1>Good possibilities.<br><em>Clear reasons.</em></h1><p>${D.goals[state.answers.goal]?E(D.goals[state.answers.goal])+' · ':''}${E(D.modes[state.answers.mode]||'Every setting')}${state.answers.duration?' · '+E(state.answers.duration)+' days planned':''}</p><div class="discovery-actions"><a class="button btn" href="#/choose">Edit my profile</a><button class="button btn" data-discovery="export">Download my profile</button></div></section><section class="discovery-shortlist"><div><span class="eyebrow">SHORTLIST · ${short.length} / 3</span><h2>Keep your strongest possibilities together.</h2></div>${short.length?`<div class="discovery-shortlist-grid">${short.map(r=>`<article><h3>${E(r.title)}</h3><p>${E(r.subtitle)}</p><a href="${config.preview(r)}">Review source →</a><button data-discovery="shortlist" data-id="${E(r.id)}">Remove</button></article>`).join('')}</div>`:'<p>Use “Add to shortlist” below to compare up to three sources.</p>'}</section><form id="discovery-filter"><div class="discovery-search">${input('q','Search these matches',p.q)}<button class="primary btn">Search</button></div><details><summary>Refine with verified source details</summary><p>Strict filters include only sources with matching evidence. Unknown metadata is excluded, so a narrow search may have no results.</p><div class="discovery-filter-grid">${input('scripture','Bible book, passage or character',p.scripture)}${filters.map(([k,l,o])=>input(k,l,p[k],o)).join('')}</div></details></form><div class="discovery-results-heading"><h2>${list.length.toLocaleString()} ${list.length===1?'possibility':'possibilities'}</h2><a href="#/matches">Clear strict filters</a></div><div class="discovery-results">${items.map(r=>`<article><div><span class="eyebrow">${E(r.status||'Source-linked starting point')}</span><h2><a href="${config.preview(r)}">${E(r.title)}</a></h2><p>${E(r.subtitle||'No subtitle supplied in the source.')}</p></div><div class="discovery-evidence"><h3>${r.matchReasons.length?'Why it may fit':'Fit still needs review'}</h3>${r.matchReasons.length?`<ul>${r.matchReasons.map(v=>`<li>${E(v)}</li>`).join('')}</ul>`:'<p>No matching evidence for the selected preferences.</p>'}<details><summary>${r.missing.length} ${r.missing.length===1?'detail':'details'} to review</summary><ul>${r.missing.map(v=>`<li>${E(v)}</li>`).join('')}</ul></details></div><div class="discovery-actions"><a class="primary btn" href="${config.preview(r)}">Preview source →</a><button class="button btn" data-discovery="shortlist" data-id="${E(r.id)}">${state.shortlist.includes(r.id)?'Remove from shortlist':'Add to shortlist'}</button></div></article>`).join('')||'<section class="discovery-empty"><h2>Give the search a little more room.</h2><p>Some source details are still unknown. Remove a strict filter or choose a broader theme.</p></section>'}</div><nav class="discovery-actions" aria-label="Match results pages">${page>1?`<a class="button btn" href="#/matches?${new URLSearchParams({...p,page:page-1})}">Previous</a>`:''}${page*12<list.length?`<a class="button btn" href="#/matches?${new URLSearchParams({...p,page:page+1})}">Next →</a>`:''}</nav><p class="discovery-foot">Match reasons identify source evidence. They do not establish an outcome, endorsement, complete manuscript, or right to adapt the material.</p>`,'Your campaign matches')}
  function render(){const r=route();if(r==='choose')intro();else if(r==='choose/questions')question();else if(r==='matches')results();else return false;return true}
  document.addEventListener('change',e=>{if(e.target.closest?.('#discovery-question')){const f=D.fields[state.step];state.answers[f.key]=new FormData(e.target.form).get('answer')||'';save()}});
  document.addEventListener('submit',e=>{if(e.target.id==='discovery-question'){e.preventDefault();state.answers[D.fields[state.step].key]=new FormData(e.target).get('answer')||'';advance()}else if(e.target.id==='discovery-filter'){e.preventDefault();location.hash='/matches?'+new URLSearchParams([...new FormData(e.target)].filter(([,v])=>v))}});
  function advance(){if(state.step+1>=(state.depth==='quick'?6:14)){state.step=0;save();location.hash='/matches'}else{state.step++;save();question()}}
  document.addEventListener('click',e=>{const b=e.target.closest?.('[data-discovery]');if(!b)return;const action=b.dataset.discovery;if(action==='start'){if(state.depth!==b.dataset.depth)state.step=0;state.depth=b.dataset.depth;save();location.hash='/choose/questions'}else if(action==='back'){state.step--;save();question()}else if(action==='skip'){delete state.answers[D.fields[state.step].key];advance()}else if(action==='shortlist'){try{state.shortlist=D.shortlist(state.shortlist,b.dataset.id);save();results()}catch(err){config.notify(err.message)}}else if(action==='export'){const blob=new Blob([JSON.stringify({schema:'lifetogether-discovery-v1',...state},null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='lifetogether-journey-profile.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}});
