    scripture: {label: 'Life & teaching of Jesus', promise: 'understand Jesus’ teaching in context and put a specific teaching into practice', terms: ['jesus', 'christ', 'gospel', 'scripture', 'red letter'], arc: ['Come and see', 'Hear the good news', 'Learn the way of Jesus', 'Practice mercy', 'Follow through the cost', 'Go and make disciples'], scripture: ['John 1:35–51', 'Mark 1:14–20', 'Matthew 5:1–12', 'Luke 10:25–37', 'Luke 9:18–27', 'Matthew 28:16–20'], practice: ['Read the passage and name what you notice about Jesus.', 'Consider where Jesus’ invitation meets your life.', 'Choose one teaching to practice this week.', 'Offer a concrete act of mercy.', 'Discuss a difficult next step with a trusted friend.', 'Invite someone to continue learning and practicing with you.']}
