function cfDetail(x){if(!x){shell(heading('This starting point is unavailable','It may be archived, restricted, or no longer part of this library.')+link(cfRoute(),'Return to campaign finder','btn primary'),'campaign-finder','Campaign finder');return;}
 const f=cfFilters(),goal=Object.hasOwn(CB.goals,f.goal)?f.goal:x.goals[0]||wsState.church.goal||'community',duration=CB.durations.includes(Number(f.duration))?Number(f.duration):CB.durations.includes(x.duration)?x.duration:CB.durations.includes(wsState.church.duration)?wsState.church.duration:40,audience=cfAudienceProfiles[f.audience]||cfAudienceProfiles[x.audiences[0]]||'Whole church',sourceRoute=x.kind==='sermon'?'sermons/'+q(x.sermonId):'record/'+q(x.recordId),matched=CF.search([x],f)[0],reasons=matched?.reasons||[x.evidence];
 shell(`<div class="cf">${link(cfRoute(),'← Back to campaign finder','cb-back')}<section class="cf-detail"><div class="cf-detail-cover tone-0"><div class="cf-card-art"><span class="cf-art-index">${E(CB.layers[x.layer])}</span><span class="cf-art-word">${E(x.title)}</span><i class="cf-art-mark" aria-hidden="true"></i></div><p>${E(x.recordId||'From your sermon library')}</p></div><div class="cf-detail-content"><span class="eyebrow">${E(x.status)}</span><h1>${E(x.title)}</h1><p class="cf-detail-subtitle">${E(x.subtitle||'No subtitle supplied in the source.')}</p><div class="cf-reasons">${reasons.filter(Boolean).map(r=>'<span>'+E(r)+'</span>').join('')}</div><dl class="cf-detail-facts"><div><dt>Intelligence library</dt><dd>${E(CB.layers[x.layer])}</dd></div><div><dt>Length in the source</dt><dd>${E(cfDuration(x))}</dd></div><div><dt>Source audience</dt><dd>${E(x.audienceText||'Not stated')}</dd></div><div><dt>Source format</dt><dd>${E(x.format||CF.types[x.type]||'Sermon notes')}</dd></div><div><dt>Source</dt><dd>${E(x.sourceLabel||x.recordId||'Your personal sermon library')}</dd></div></dl><div class="toolbar">${link(sourceRoute,'View original source '+icon('external'),'btn small')}${x.kind==='catalog'?saveBtn(byId.get(x.recordId))+compareBtn(byId.get(x.recordId)):''}</div>
 ${x.restricted?`<div class="cf-detail-note"><h3>A reference to learn from.</h3><p>${E(x.restrictionReason||'This source is marked for restricted use. It can be reviewed in the catalog but is not available to use in a campaign.')}</p></div>`:`<form id="cf-start-form" class="cf-search-panel"><input type="hidden" name="candidateId" value="${E(x.id)}"><div class="eyebrow">Make it your church’s next chapter</div><h2>Shape the starting point.</h2><p>Your title, subtitle, and source will travel into a new campaign. Choose the direction you want to develop.</p><div class="cf-filters">${cfSelect('goal','Our ministry goal',goal,Object.entries(CB.goals).map(([k,g])=>[k,g.label]))}${cfSelect('duration','Our planned length',duration,CB.durations.map(n=>[n,n+' days']))}${cfSelect('audience','Our audience',audience,[...new Set(Object.values(cfAudienceProfiles))].map(v=>[v,v]))}</div><p class="small muted">The planned length is your development choice. It does not imply a finished edition exists.${!x.duration?' The source does not specify a single campaign length.':''}</p><button type="submit" class="btn primary">Build from this idea ${icon('arrow')}</button></form>`}</div></section></div>`,'campaign-finder',x.title);}
function finderSubmit(e){if(!['cf-form','cf-start-form'].includes(e.target.id))return false;e.preventDefault();try{const f=Object.fromEntries(new FormData(e.target));if(e.target.id==='cf-form'){nav('campaign-finder',Object.fromEntries(cfFilterKeys.map(k=>[k,CB.clean(f[k]||'',250)])));return true;}
 if(cbConflict||wsConflict)throw Error('Reload the newer workspace before creating a campaign.');
 const x=cfIndex().find(x=>x.id===f.candidateId);if(!x||x.restricted)throw Error('This source is not available to start a campaign.');if(cbWorkspace.campaigns.length>=25)throw Error('Back up and archive a campaign before adding another.');
 if(!Object.hasOwn(CB.goals,f.goal)||!CB.durations.includes(Number(f.duration))||!Object.values(cfAudienceProfiles).includes(f.audience))throw Error('Choose a ministry goal, planned length, and audience.');
 const original=x.kind==='catalog'?byId.get(x.recordId):wsState.sermons.find(s=>s.id===x.sermonId&&!s.archived&&s.permission!=='restricted');if(!original||(x.kind==='catalog'&&CB.denied(original)))throw Error('This source is not available to start a campaign.');
 const c=CB.create(wsState.church);c.title=x.title;c.subtitle=x.subtitle;c.profile.goal=f.goal;c.profile.duration=Number(f.duration);c.profile.audience=f.audience;c.sources=[x.kind==='catalog'?CB.fromRecord(original):WS.sourceCopy(original,CB)];cbWorkspace.campaigns.unshift(c);cbOpen(c,'vision');toast('Your campaign is ready to shape. The original source stays attached.');
 }catch(err){toast(err.message);}return true;}
document.addEventListener('change',e=>{if(e.target.tagName==='SELECT'&&e.target.closest?.('#cf-form'))finderSubmit({target:e.target.closest('#cf-form'),preventDefault(){}});});
try{const raw=JSON.parse(localStorage.getItem(cbKey)||'null');if(raw&&Array.isArray(raw.campaigns)){cbWorkspace.campaigns=raw.campaigns.map(x=>{const c=CB.importCampaign(x);c.id=CB.clean(x.id,100);c.updatedAt=CB.clean(x.updatedAt,50);c.createdAt=CB.clean(x.createdAt,50);return c;});cbWorkspace.activeId=raw.activeId||'';}}catch{cbStorageError='A saved workspace could not be opened. Import a campaign backup to recover it. Existing storage has not been overwritten.';cbConflict=true;}
function cbCurrent(){const route=currentRoute();return cbWorkspace.campaigns.find(c=>c.id===route[1]);}
function cbPersist(immediate=false){clearTimeout(cbSaveTimer);const run=()=>{if(cbConflict){cbStorageError='A newer workspace is open in another tab. Reload before editing, or download your current campaign to keep these changes.';cbSaveStatus();return;}try{const json=JSON.stringify(cbWorkspace);if(new Blob([json]).size>3500000)throw Error('Workspace storage is full. Download a backup and archive completed campaigns.');localStorage.setItem(cbKey,json);cbStorageError='';}catch(e){cbStorageError=e.message||'Device storage is unavailable. Download a backup to keep this campaign.';}cbSaveStatus();};if(immediate)run();else cbSaveTimer=setTimeout(run,300);}
function cbSaveStatus(){const el=$('#cb-save-status');if(el){el.textContent=cbStorageError||'Saved on this device';el.className=cbStorageError?'cb-save cb-warning':'cb-save';}}
function cbTouch(c){c.updatedAt=new Date().toISOString();c.review.approved=false;cbPersist();cbSaveStatus();}
function cbOpen(c,step){cbWorkspace.activeId=c.id;cbUI.sourceEdit='';cbUI.newSource=false;cbUI.asset='';cbPersist(true);nav('campaigns/'+c.id,{step:step||cbSteps[c.step||0][0]});}
function cbStart(seedRecord){if(cbWorkspace.campaigns.length>=25)throw Error('Keep up to 25 campaigns on this device. Back up and archive a completed campaign to make room.');const c=CB.create(wsState.church);if(seedRecord){const r=byId.get(seedRecord);if(r&&CB.catalogLayer(r)){c.sources=[CB.fromRecord(r)];c.title=r['Campaign Title'];c.subtitle=r.Subtitle||'';}}cbWorkspace.campaigns.unshift(c);cbOpen(c,'vision');return c;}
function cbGet(c,path){return path.split('.').reduce((o,k)=>o?.[k],c);}
function cbSet(c,path,value){const parts=path.split('.');if(parts.some(x=>['__proto__','prototype','constructor'].includes(x)))return;let target=c;for(const key of parts.slice(0,-1)){if(!target[key])return;target=target[key];}target[parts.at(-1)]=value;}
function cbField(c,path,label,{type='text',help='',placeholder='',options=[],full=false,rows=3,min=0,max=1000000}={}){
  const value=cbGet(c,path)??'',attrs=`id="cb-${E(path.replace(/\./g,'-'))}" data-cb-field="${E(path)}"`,field=type==='textarea'?`<textarea ${attrs} rows="${rows}" maxlength="${path.endsWith('.body')?60000:4000}" placeholder="${E(placeholder)}">${E(value)}</textarea>`:type==='select'?`<select ${attrs}>${options.map(o=>{const [v,l]=Array.isArray(o)?o:[o,o];return `<option value="${E(v)}" ${String(v)===String(value)?'selected':''}>${E(l)}</option>`;}).join('')}</select>`:`<input ${attrs} type="${type}" value="${E(value)}" placeholder="${E(placeholder)}" ${type==='number'?`min="${min}" max="${max}" step="1"`:type==='date'?'':'maxlength="600"'}>`;
  return `<label class="field ${full?'full':''}"><span>${E(label)}</span>${field}${help?`<small>${E(help)}</small>`:''}</label>`;
}
function cbCheck(path,label,value){return `<label class="cb-check"><input type="checkbox" data-cb-field="${E(path)}" ${value?'checked':''}><span>${E(label)}</span></label>`;}
const cbButton=(action,label,cls='btn',extra='')=>`<button class="${cls}" data-cb="${action}" ${extra}>${label}</button>`;
function cbEmpty(title,text,action=''){return `<div class="cb-empty"><div class="cb-empty-icon">${icon('library')}</div><h3>${E(title)}</h3><p>${E(text)}</p>${action}</div>`;}
function cbHeader(number,title,description,action=''){return `<div class="cb-section-heading"><div><div class="eyebrow">${E(number)}</div><h2>${E(title)}</h2><p>${E(description)}</p></div>${action}</div>`;}
function cbSourceBadge(s){return `<span class="cb-source-badge ${E(s.layer)}">${E(CB.layers[s.layer])}</span>`;}
function cbDate(value){if(!value)return 'Date to set';return new Intl.DateTimeFormat('en-US',{month:'short',day:'numeric',year:'numeric',timeZone:'UTC'}).format(new Date(value+'T12:00:00Z'));}
function campaignsPage(){const c=cbCurrent();if(!currentRoute()[1]){cbDashboard();return;}if(!c){shell(heading('Campaign not on this device','Import its campaign backup or return to your workspace.')+link('campaigns','Open campaign workspace','btn primary'),'campaigns','Campaign builder');return;}
  const step=Math.max(0,cbSteps.findIndex(x=>x[0]===(params().get('step')||cbSteps[c.step||0][0])));if(c.step!==step){c.step=step;cbPersist();}cbWorkspace.activeId=c.id;
  const ready=CB.readiness(c),complete=ready.filter(x=>x.done).length,views=[cbVision,cbSources,cbScope,cbBlueprint,cbStudio,cbLaunch,cbReview];
  const body=`<div class="cb"><div class="cb-workspace-head"><div>${link('campaigns','← All campaigns','cb-back')}<div class="cb-titleline"><h1>${E(c.title||'Your new campaign')}</h1><span class="cb-pill">${c.example?'Example · editable':'Working campaign'}</span></div><p>${E(c.profile.church||'Your church')} <span>·</span> ${c.profile.duration} days ${c.profile.launchDate?' <span>·</span> Launch '+cbDate(c.profile.launchDate):''}</p></div><div class="cb-head-actions"><span id="cb-save-status" class="cb-save ${cbStorageError?'cb-warning':''}" role="status">${E(cbStorageError||'Saved on this device')}</span>${link('calendar','Church calendar','btn small')}${cbButton('backup',icon('download')+' Save a backup','btn small')}</div></div>
  <div class="cb-stage-label"><span class="eyebrow">Your campaign, thoughtfully built</span><span>Step ${step+1} of ${cbSteps.length}</span></div><nav class="cb-steps" aria-label="Campaign building steps">${cbSteps.map(([key,label,sub],i)=>`<a href="#/campaigns/${E(c.id)}?step=${key}" ${step===i?'aria-current="step"':''} class="cb-step ${step===i?'current':''}"><span class="cb-step-number">${String(i+1).padStart(2,'0')}</span><span><strong>${label}</strong><small>${sub}</small></span></a>`).join('')}</nav>
  <div class="cb-workgrid"><section class="cb-main">${views[step](c)}</section><aside class="cb-summary"><div class="cb-compass-heading"><span class="eyebrow">Campaign compass</span>${icon('network')}</div><h3>${E(CB.goals[c.profile.goal].label)}</h3><p>${E(c.profile.objective||'Name the change you hope people will practice together.')}</p><div class="cb-mini-stats"><div><b>${CB.weekCount(c)}</b><span>teaching weeks</span></div><div><b>${CB.selected(c).length}</b><span>selected sources</span></div><div><b>${CB.descriptors(c).length}</b><span>planned resources</span></div></div><div class="cb-summary-sources">${Object.entries(CB.layers).map(([key,label])=>`<div><span class="cb-dot ${key}"></span><span>${label}</span><b>${CB.selected(c).filter(s=>s.layer===key).length}</b></div>`).join('')}</div><div class="cb-progress-label"><strong>Ready to lead</strong><span>${complete} of ${ready.length}</span></div><div class="cb-progress"><span style="width:${complete/ready.length*100}%"></span></div><p class="cb-helper">Your plan becomes ready as sources, teaching, resources, and team preparation are reviewed.</p>${link('campaigns/'+c.id+'?step=review','View readiness checklist →','cb-text-link')}<div class="cb-local-note">Your sermons and campaign stay in this browser. Download a backup to move between devices.</div></aside></div>
  <div class="cb-bottom"><span>Step ${step+1} of ${cbSteps.length} <span class="muted">· ${cbSteps[step][1]}</span></span><div>${step?link('campaigns/'+c.id+'?step='+cbSteps[step-1][0],'← Back','btn'):link('campaigns','Back to campaigns','btn')}${step<6?link('campaigns/'+c.id+'?step='+cbSteps[step+1][0],cbSteps[step+1][1]+' '+icon('arrow'),'btn primary'):cbButton('export-html','Download campaign playbook '+icon('download'),'btn primary')}</div></div></div>`;
  shell(body,'campaigns','Campaign builder');
}
function cbDashboard(){shell(`<div class="cb cb-dashboard"><div class="cb-dashboard-kicker"><span class="eyebrow">The campaign studio</span><span>Ideas become shared experiences.</span></div><section class="cb-hero"><div class="cb-hero-copy"><div class="cb-hero-rule"><span></span> Made for your church</div><h1>A shared vision.<br><em>A living journey.</em></h1><p>Bring your teaching, trusted resources, and your church’s story into a campaign people can live out together.</p><div class="cb-hero-actions">${cbButton('new','Start a campaign '+icon('arrow'),'btn cb-light')}${link('campaign-finder','Find a campaign '+icon('search'),'btn cb-ghost')}${cbButton('example','Explore an example','btn cb-ghost')}</div><span class="cb-hero-note">Thoughtfully guided. Entirely shaped by you.</span></div><div class="cb-planning-desk" role="img" aria-label="Your sermons, LifeTogether resources, and global church references brought together in one campaign"><div class="cb-desk-caption"><span>THREE LIBRARIES</span><span>ONE SHARED DIRECTION</span></div><div class="cb-folio-shadow"></div><div class="cb-source-sheet sheet-church"><span>03 / CHURCH INTELLIGENCE</span><i></i><i></i><i></i></div><div class="cb-source-sheet sheet-lifetogether"><span>02 / LIFETOGETHER INTELLIGENCE</span><i></i><i></i><i></i></div><div class="cb-source-sheet sheet-pastor"><span>01 / SERMON INTELLIGENCE</span><i></i><i></i><i></i></div><div class="cb-campaign-folio"><div class="cb-folio-top"><span>LIFE<br>TOGETHER</span><span>CAMPAIGN<br>PLANNER</span></div><div class="cb-folio-title">One church.<br>One shared<br><em>journey.</em></div><div class="cb-folio-path"><span></span><span></span><span></span><span></span><span></span><span></span></div><div class="cb-folio-footer"><span>Your voice.<br>Your people. Your purpose.</span>${icon('arrow')}</div></div><span class="cb-desk-annotation">From Sunday’s message<br>to everyday faith.</span></div></section>
  <div class="cb-library-intro">${[['pastor','Your voice leads the way','Import sermons, paste notes, and preserve your biblical emphasis.'],['lifetogether','A rich foundation to build on','Search the LifeTogether catalog and recovered campaign concepts.'],['church','A wider world of wisdom','Explore indexed church references and add resources you trust.']].map(([layer,title,desc],i)=>`<article><div class="cb-library-intro-top"><span class="cb-source-index">0${i+1}</span><span class="cb-source-badge ${layer}">${CB.layers[layer]}</span></div><h3>${title}</h3><p>${desc}</p></article>`).join('')}</div>
  <div class="cb-section-heading"><div><div class="eyebrow">Your workspace</div><h2>Campaigns you’re shaping<span class="cb-heading-count">${cbWorkspace.campaigns.length}</span></h2><p>Pick up where you left off. Your work is saved on this device.</p></div><label class="btn cb-import-button ws-upload">${icon('download')} Import a campaign<input type="file" id="cb-import-campaign" accept="application/json,.json" aria-label="Import a campaign"></label></div>
  ${cbStorageError?`<div class="notice" role="alert">${E(cbStorageError)}</div>`:''}${cbWorkspace.campaigns.length?`<div class="cb-projects">${cbWorkspace.campaigns.map((c,i)=>{const checks=CB.readiness(c),n=checks.filter(x=>x.done).length,route='campaigns/'+c.id+'?step='+cbSteps[c.step||0][0];return `<article class="cb-project cb-project-tone-${i%3}"><div class="cb-project-cover" aria-hidden="true"><span class="cb-cover-index">L / T</span><div><strong>${c.profile.duration}</strong><span>DAY JOURNEY</span></div><span class="cb-cover-line"></span></div><div class="cb-project-body"><div class="cb-project-top"><span class="cb-pill">${c.example?'Example':'Draft campaign'}</span><span>${CB.weekCount(c)} teaching weeks</span></div><h3>${link(route,E(c.title||'Untitled campaign'))}</h3><p>${E(c.subtitle||c.profile.objective||'Start with the change you hope to see in your church.')}</p><div class="cb-project-meta">${E(c.profile.church||'Church to add')}<span>·</span>${c.profile.launchDate?cbDate(c.profile.launchDate):'Launch date to set'}</div><div class="cb-project-readiness"><div class="cb-progress"><span style="width:${n/checks.length*100}%"></span></div><span>${n}/${checks.length} ready</span></div><div class="cb-project-bottom">${link(route,'Continue shaping '+icon('arrow'),'cb-project-resume')}<div>${cbButton('duplicate','Duplicate','btn flat small',`data-id="${E(c.id)}"`)}${cbButton('delete','Archive','btn flat small',`data-id="${E(c.id)}"`)}</div></div></div></article>`;}).join('')}</div>`:`<div class="cb-empty cb-empty-campaign"><div class="cb-empty-illustration" aria-hidden="true"><span></span><span></span><span>${icon('plus')}</span></div><div><div class="eyebrow">Room for your next idea</div><h3>Your next campaign starts here.</h3><p>Choose a transformation goal, bring your sources together, and build the experience one thoughtful step at a time.</p></div>${cbButton('new','Create your first campaign '+icon('arrow'),'btn primary')}</div>`}
  <div class="cb-journey-heading"><span class="eyebrow">From vision to a shared experience</span><span>Seven considered steps</span></div><div class="cb-flow-strip">${cbSteps.map(([key,label],i)=>`<div><span>${String(i+1).padStart(2,'0')}</span><strong>${label}</strong>${i<cbSteps.length-1?icon('arrow'):icon('check')}</div>`).join('')}</div></div>`,'campaigns','Campaign builder');}
function cbVision(c){const p=c.profile;return cbHeader('01 / Vision','What do you hope will change?','Start with your people and the transformation you want to cultivate.', '<div class="cb-profile-actions">'+wsButton('apply-church','Apply church profile','','btn small')+link('church','Edit shared profile','cb-text-link')+'</div>')+`<div class="cb-panel"><h3>The people and the purpose</h3><div class="formgrid">${cbField(c,'profile.church','Church name',{placeholder:'Your church'})}${cbField(c,'profile.pastor','Lead pastor / teaching voice',{placeholder:'Name'})}${cbField(c,'profile.goal','Primary focus',{type:'select',options:Object.entries(CB.goals).map(([id,g])=>[id,g.label])})}${cbField(c,'profile.audience','Who is this for?',{type:'select',options:['Whole church','Adults & small groups','Families & households','Youth & students','Children & caregivers','Leaders & volunteers','A pilot group']})}${cbField(c,'profile.objective','By the end, people will…',{type:'textarea',full:true,placeholder:CB.goals[p.goal].promise,help:'Describe a change people can practice, not just information they will learn.'})}</div>${cbButton('suggest-objective','Use the suggested transformation goal','btn flat small')}<div class="formgrid cb-space">${cbField(c,'profile.context','What is happening in your church right now?',{type:'textarea',full:true,placeholder:'The needs, questions, and opportunities behind this campaign.'})}${cbField(c,'profile.mission','Mission and values to carry through',{type:'textarea',full:true,placeholder:'What makes this church’s calling distinct?'})}</div></div>
  <div class="cb-panel"><h3>Give the invitation a name</h3><div class="formgrid">${cbField(c,'title','Campaign title',{full:true,placeholder:'A clear invitation your church can remember'})}${cbField(c,'subtitle','Campaign subtitle',{full:true,placeholder:'The transformation promise in a sentence'})}${cbField(c,'profile.duration','Campaign length',{type:'select',options:CB.durations.map(n=>[n,n+' days · '+Math.ceil(n/7)+' teaching '+(Math.ceil(n/7)===1?'week':'weeks')])})}${cbField(c,'profile.launchDate','Launch date',{type:'date',help:'Day 1 is your opening gathering. All dates follow this date.'})}</div></div>
  <details class="cb-panel"><summary>Your voice and theological direction</summary><div class="formgrid cb-space">${cbField(c,'profile.theology','Theological convictions and boundaries',{type:'textarea',full:true,placeholder:'Denominational language, pastoral priorities, and topics to handle carefully.'})}${cbField(c,'profile.voice','How should the teaching sound?',{type:'textarea',full:true})}${cbField(c,'profile.translation','Scripture translation',{type:'select',options:['NIV','ESV','NLT','CSB','NKJV','KJV','NRSVUE','Other — record in theological notes']})}${cbField(c,'profile.sermonMinutes','Sermon length in minutes',{type:'number',min:10,max:90})}</div></details>
  <details class="cb-panel"><summary>Design the movement beyond the message</summary><p class="cb-helper">Give people an experience, a community, and a next step that outlasts the campaign.</p><div class="formgrid">${cbField(c,'profile.catalytic','The catalytic launch experience',{type:'textarea',full:true,placeholder:'A shared meal, prayer gathering, serving moment, or response invitation.'})}${cbField(c,'profile.champions','Who will champion it?',{type:'textarea',full:true,placeholder:'Pastors, hosts, families, ministry leaders, and trusted voices.'})}${cbField(c,'profile.distribution','How will people participate?',{type:'textarea',full:true})}${cbField(c,'profile.stories','How will you hear and share true stories?',{type:'textarea',full:true,placeholder:'Listen through hosts, invite stories, and confirm permission before sharing.'})}${cbField(c,'profile.multiplication','How will this develop new leaders?',{type:'textarea',full:true})}</div></details>
  <div class="cb-panel cb-accent"><h3>Plan the next faithful step now</h3>${cbField(c,'profile.nextStep','What happens after the campaign?',{type:'textarea',placeholder:'The next group experience, habit, service opportunity, or ministry pathway.'})}</div>`;}
function cbSourceEditor(c){let s=c.sources.find(x=>x.id===cbUI.sourceEdit);const creating=!s;if(!s)s=CB.source({layer:cbUI.layer==='lifetogether'?'lifetogether':cbUI.layer,title:''});
 const f=(name,label,type='text',placeholder='')=>`<label class="field ${['notes','bigIdea','practice','subtitle','url','locator'].includes(name)?'full':''}"><span>${label}</span>${type==='textarea'?`<textarea name="${name}" rows="${name==='notes'?8:2}" maxlength="${name==='notes'?60000:1800}" placeholder="${E(placeholder)}">${E(s[name])}</textarea>`:`<input name="${name}" type="${type}" value="${E(s[name])}" ${name==='title'?'required':''} maxlength="600" placeholder="${E(placeholder)}">`}</label>`;
 return `<div class="cb-panel cb-source-editor"><div class="cb-section-heading"><div><div class="eyebrow">${creating?'Add':'Edit'} a source</div><h3>${creating?'Bring a teaching into the workspace':E(s.title)}</h3></div>${cbButton('close-source','Close','btn small')}</div><form id="cb-source-form"><input type="hidden" name="sourceId" value="${creating?'':E(s.id)}"><div class="formgrid">${f('title','Title')}${f('speaker','Speaker / author')}${f('subtitle','Subtitle')}${f('church','Church / organization')}${f('series','Series title')}${f('date','Date preached / recorded','date')}${f('scripture','Primary Scripture')}${f('url','Source link','url','Optional video, audio, article, or document link')}${f('locator','Source location','text','Page, chapter, timecode, or section')}${f('bigIdea','Recorded big idea','textarea','What does the source actually teach?')}${f('practice','Recorded application / next step','textarea')}${f('notes','Sermon notes or transcript','textarea','Paste the teaching you want to work from. Links are stored as references; their content is not automatically transcribed.')}
 <label class="field">Intelligence library<select name="layer">${Object.entries(CB.layers).map(([v,l])=>`<option value="${v}" ${v===s.layer?'selected':''}>${l}</option>`).join('')}</select></label><label class="field">How may this source be used?<select name="permission" ${s.catalogRestricted?'disabled':''}>${[['internal','Internal planning only'],['owned','Our church owns this material'],['authorized','Permission covers this adaptation'],['reference','Reference — adaptation rights unconfirmed'],['restricted','Restricted — exclude from building']].map(([v,l])=>`<option value="${v}" ${s.permission===v?'selected':''}>${l}</option>`).join('')}</select></label>${s.catalogRestricted?'<p class="cb-helper full">The original catalog holds this source for reference only. It is excluded from teaching drafts. Add a separate source if you have permission-cleared teaching to use.</p>':''}<label class="cb-check full"><input type="checkbox" name="complete" ${s.complete?'checked':''}><span>I have supplied the teaching needed for this campaign.</span></label></div><div class="formactions"><button type="submit" class="btn primary">${creating?'Add to campaign':'Save source'}</button>${cbButton('close-source','Cancel','btn')}</div></form></div>`;
}
function cbSources(c){const selected=CB.selected(c),layer=cbUI.layer;
 const intro=cbHeader('02 / Intelligence','Build from three libraries','Your pastoral direction brings the sources together. Select the ideas and teaching you want to carry into this campaign.');
 const tabs=`<div class="cb-library-tabs" role="tablist" aria-label="Intelligence libraries">${Object.entries(CB.layers).map(([key,label],i)=>`<button role="tab" aria-selected="${layer===key}" data-cb="layer" data-layer="${key}" class="${layer===key?'selected':''}"><span class="cb-library-number ${key}">${i+1}</span><span><strong>${label}</strong><small>${key==='pastor'?'Your sermons and notes':key==='lifetogether'?'The shared LifeTogether catalog':'The wider church’s indexed resources'}</small></span></button>`).join('')}</div>`;
 if(cbUI.newSource||cbUI.sourceEdit)return intro+tabs+cbSourceEditor(c);
 const imported=c.sources.filter(s=>s.layer===layer),selectedIDs=new Set(c.sources.map(s=>s.recordId).filter(Boolean));let content='';
 const addControls=`<div class="cb-import-actions">${cbButton('add-source',icon('plus')+' Add notes or a link','btn primary')}<label class="btn">Import sermon files<input type="file" id="cb-import-sources" accept=".txt,.md,.csv,.json,.docx,text/plain,text/markdown,application/json" multiple hidden></label>${cbButton('source-template','Download import template','btn flat small')}</div>`;
 if(layer==='pastor')content=`<div class="cb-panel cb-accent"><h3>Your teaching is the starting point</h3><p>Bring in one sermon or a whole series. Keep the original title, speaker, Scripture, and application connected to the campaign.</p>${addControls}<p class="cb-helper">Word (.docx), text, Markdown, CSV, and JSON. For audio, video, or PDF, add a reference link and paste the transcript or notes. Imports stay on this device.</p></div>`;
 else {const hits=CB.searchCatalog(records,layer,cbUI.query,c.profile.goal),pages=Math.max(1,Math.ceil(hits.length/8));cbUI.page=Math.min(cbUI.page,pages);const slice=hits.slice((cbUI.page-1)*8,cbUI.page*8);
 content=`<div class="cb-panel"><div class="cb-section-heading"><div><h3>${layer==='lifetogether'?'Find a trusted starting point':'Learn from the global church'}</h3><p>${layer==='lifetogether'?'Titles and concepts from the existing LifeTogether library. Add teaching notes to develop source-based resources.':'Search the church reference records already indexed in this library, or add a resource you trust. This is an indexed collection, not a live search of every church.'}</p></div></div><div class="cb-searchbar"><input type="search" id="cb-source-search" data-cb-search="true" aria-label="Search intelligence library" placeholder="Search a title, theme, or author…" value="${E(cbUI.query)}">${cbButton('search','Search','btn primary')}</div><div class="cb-search-meta"><span>${fmt(hits.length)} matching records</span><span>Relevant to ${E(CB.goals[c.profile.goal].label.toLowerCase())}</span></div>${slice.length?`<div class="cb-resource-grid">${slice.map(({r,score})=>`<article class="cb-resource-card"><div>${cbSourceBadge({layer})}<h4>${E(r['Campaign Title'])}</h4><p>${E(r.Subtitle||r.Category||'Subtitle not supplied')}</p><small>${r._memory?'Recovered concept':layer==='church'?'Church reference · rights unconfirmed':'Catalog record · teaching content to attach'}</small></div><div class="cb-resource-actions">${link('record/'+q(r['Master ID']),'Inspect source ↗','small')}${cbButton('add-record',selectedIDs.has(r['Master ID'])?'Added ✓':'+ Use in campaign','btn small',`data-id="${E(r['Master ID'])}" ${selectedIDs.has(r['Master ID'])?'disabled':''}`)}</div></article>`).join('')}</div>`:cbEmpty('No matching resources','Try a shorter phrase, or add a resource from your own research.')}<div class="pager"><span>Page ${cbUI.page} of ${pages}</span><div>${cbButton('source-page','Previous','btn small',`data-page="${cbUI.page-1}" ${cbUI.page===1?'disabled':''}`)}${cbButton('source-page','Next','btn small',`data-page="${cbUI.page+1}" ${cbUI.page===pages?'disabled':''}`)}</div></div><div class="cb-divider"></div>${addControls}</div>`;
 }
 const chosen=imported.length?`<div class="cb-panel"><div class="cb-section-heading"><div><h3>Sources in this library</h3><p>${imported.length} attached · ${imported.filter(s=>s.selected&&s.permission!=='restricted').length} selected for this campaign</p></div></div><div class="cb-selected-list">${imported.map(s=>`<article class="cb-selected-source"><label class="cb-check"><input type="checkbox" data-cb-select-source="${E(s.id)}" ${s.selected?'checked':''} ${s.permission==='restricted'?'disabled':''} aria-label="Use ${E(s.title)}"><span><strong>${E(s.title)}</strong><small>${E(s.subtitle||s.scripture||s.speaker||'Add Scripture and teaching notes')}</small></span></label><div class="cb-source-meta"><span>${s.catalogRestricted?'Catalog reference only':s.permission==='restricted'?'Restricted':s.notes||s.bigIdea?'Teaching notes attached':'Title / reference only'}</span><span>${({internal:'Internal planning',owned:'Church-owned',authorized:'Adaptation authorized',reference:'Rights to confirm',restricted:'Excluded'})[s.permission]}</span></div><div class="cb-source-buttons">${cbButton('edit-source','Edit notes','btn small',`data-id="${E(s.id)}"`)}${cbButton('remove-source','Remove','btn flat small',`data-id="${E(s.id)}"`)}</div></article>`).join('')}</div></div>`:layer==='pastor'?cbEmpty('Your sermon library is ready for you','Add a message or import a series to shape the campaign around your own teaching.'):'';
 return intro+tabs+(layer==='pastor'?wsCampaignLibrary(c)+wsButton('save-campaign-sermons','Save campaign sermons to my library','','btn small'):'')+content+chosen+`<div class="cb-callout"><strong>${selected.length} sources selected across all three libraries.</strong><p>The weekly blueprint lets you decide exactly which sources shape each teaching. A title-only record stays a concept until you add the teaching.</p>${link('campaigns/'+c.id+'?step=blueprint','See the weekly blueprint →','cb-text-link')}</div>`;
}
function cbScope(c){const count=CB.components.filter(x=>c.scope[x.id]==='now').length;return cbHeader('03 / Experience','Choose the experience your church can lead well','Start with the essential rhythm, then add the components your people and team need.')+`<div class="cb-panel cb-accent"><div class="cb-section-heading"><div><h3>A connected weekly rhythm</h3><p>Gather around Scripture → talk in community → practice daily → respond together.</p></div><span class="cb-pill">${count} components included</span></div><div class="cb-presets">${cbButton('preset-pilot','Simple pilot','btn',`data-preset="pilot"`)}${cbButton('preset-church','Whole-church campaign','btn',`data-preset="church"`)}${cbButton('preset-full','Full campaign experience','btn',`data-preset="full"`)}</div><p class="cb-helper">Presets change the scope below. Existing resource drafts are retained if you change your mind.</p></div><div class="cb-scope-grid">${CB.components.map(comp=>`<article class="cb-scope-card ${c.scope[comp.id]==='now'?'included':''}"><div class="cb-scope-icon">${icon(c.scope[comp.id]==='now'?'check':'plus')}</div><div><h3>${comp.label}</h3><p>${comp.description}</p><label class="field"><span class="sr-only">Scope for ${comp.label}</span><select data-cb-field="scope.${comp.id}" aria-label="Scope for ${comp.label}">${[['now','Include now'],['later','Plan for later'],['off','Not this campaign']].map(([v,l])=>`<option value="${v}" ${c.scope[comp.id]===v?'selected':''}>${l}</option>`).join('')}</select></label></div></article>`).join('')}</div><div class="cb-panel cb-space"><h3>Make the rhythm manageable</h3><div class="formgrid">${cbField(c,'profile.groupMinutes','Group session length in minutes',{type:'number',min:30,max:120})}${cbField(c,'profile.devotionalMinutes','Daily reading and practice in minutes',{type:'number',min:5,max:30})}</div><p class="cb-helper">Children, youth, and family editions can be phased in. For a family legacy campaign, consider testing with families before a wider church launch.</p></div>`;}
function cbBlueprint(c){const ww=CB.syncWeeks(c),ss=CB.selected(c);return cbHeader('04 / Blueprint','One message. A connected week.','Shape the teaching arc, choose its sources, and connect each message to practice.')+`<div class="cb-toolbar"><span class="cb-pill">${ww.length} teaching weeks · ${c.profile.duration} days</span>${cbButton('assign-sources','Fill empty source assignments','btn small')}<span class="cb-helper">Your edits are preserved.</span></div>${ss.length?'':`<div class="cb-callout"><strong>Bring your teaching into the plan.</strong><p>The starting arc below is an editorial suggestion. Add a sermon source to make it yours.</p>${link('campaigns/'+c.id+'?step=sources','Add intelligence sources →','cb-text-link')}</div>`}
  <div class="cb-week-list">${ww.map((w,i)=>`<details class="cb-week" ${w.number===cbUI.week?'open':''}><summary><span class="cb-week-n">${String(w.number).padStart(2,'0')}</span><span class="cb-week-summary"><strong>${E(w.title)}</strong><small>${cbDate(CB.date(c.profile.launchDate,i*7))} · Days ${i*7+1}–${Math.min(c.profile.duration,(i+1)*7)}</small></span><span class="cb-pill ${w.reviewed?'success':''}">${w.reviewed?'Reviewed':w.sourceIds.length?'Source connected':'Editorial suggestion'}</span></summary><div class="cb-week-body"><div class="formgrid">${cbField(c,'weeks.'+i+'.title','Week '+w.number+' teaching title',{full:true})}${cbField(c,'weeks.'+i+'.bigIdea','Big idea',{type:'textarea',full:true})}${cbField(c,'weeks.'+i+'.scripture','Primary Scripture',{full:true,help:w.scriptureSuggested?'Suggested passage. Confirm its context and fit before teaching.':'From the teaching plan.'})}${cbField(c,'weeks.'+i+'.practice','Practice / response',{type:'textarea',full:true})}${cbField(c,'weeks.'+i+'.groupQuestion','Small-group conversation starter',{type:'textarea',full:true})}${cbField(c,'weeks.'+i+'.familyPractice','Family / household connection',{type:'textarea',full:true})}</div><div class="cb-week-sources"><h4>Sources shaping this week</h4>${ss.length?ss.map(s=>`<div class="cb-week-source-row"><label class="cb-check"><input type="checkbox" data-cb-week-source="${i}" data-id="${E(s.id)}" ${w.sourceIds.includes(s.id)?'checked':''}><span>${E(s.title)}<small>${E(CB.layers[s.layer])}${s.layer==='church'&&!['owned','authorized'].includes(s.permission)?' · reference context only':''}</small></span></label>${(s.bigIdea||s.scripture||s.practice)?cbButton('use-source-teaching','Use teaching notes','btn small',`data-week="${i}" data-id="${E(s.id)}"`):''}</div>`).join(''):'<p class="cb-helper">No selected sources yet.</p>'}</div>${cbCheck('weeks.'+i+'.reviewed','I have reviewed this week’s teaching, Scripture, and application.',w.reviewed)}<p class="cb-helper">Changing a teaching plan marks it for review. Existing resource drafts are preserved; regenerate a draft when you want it to use the revised plan.</p></div></details>`).join('')}</div>
  <div class="cb-panel cb-space"><h3>Your daily rhythm</h3><p>Every seventh day is a gathering and reflection. The days in between carry the message into everyday life.</p><div class="cb-calendar">${CB.days(c).map(d=>`<div class="cb-day ${d.rhythm===0?'gather':''}"><span>Day ${d.number}</span><strong>${d.rhythm===0?'Gather':d.rhythm===6?'Reflect':'Practice'}</strong><small>${d.date?cbDate(d.date).replace(/, \d{4}/,''):'Week '+d.week}</small></div>`).join('')}</div></div>`;}
function cbStudio(c){const ds=CB.descriptors(c),filtered=ds.filter(d=>!cbUI.type||d.type===cbUI.type),active=filtered.find(d=>d.id===cbUI.asset)||filtered[0];if(active)cbUI.asset=active.id;const a=active?c.assets[active.id]:null,built=ds.filter(d=>c.assets[d.id]).length,reviewed=ds.filter(d=>c.assets[d.id]?.status==='reviewed').length;
 return cbHeader('05 / Resource studio','Shape the resources people will use','Turn the weekly plan into editable drafts, then add your teaching, stories, and pastoral judgment.',cbButton('build-assets',built?'Create missing drafts':'Build editable drafts','btn primary'))+`<div class="cb-studio-stats"><span><b>${ds.length}</b> planned</span><span><b>${built}</b> drafted</span><span><b>${reviewed}</b> reviewed</span></div><div class="cb-callout"><strong>Your source-connected working drafts</strong><p>The builder combines your weekly plan, supplied teaching notes, and editorial prompts. Drafts are not automatically researched or written by an AI service. Add the full exposition and true stories, then review each resource.</p></div>${!ds.length?cbEmpty('Choose what you want to create','Include at least one component in the Experience step.',link('campaigns/'+c.id+'?step=scope','Choose components','btn primary')):`<div class="cb-studio"><aside class="cb-asset-list"><label class="field"><span>Resource type</span><select id="cb-resource-type">${[['','All included resources'],...CB.components.filter(x=>c.scope[x.id]==='now').map(x=>[x.id,x.label])].map(([v,l])=>`<option value="${v}" ${cbUI.type===v?'selected':''}>${l}</option>`).join('')}</select></label><div class="cb-asset-nav" aria-label="Campaign resources">${filtered.map(d=>`<button data-cb="asset" data-id="${d.id}" class="${d.id===active?.id?'current':''}" ${d.id===active?.id?'aria-current="true"':''}><span>${E(d.label)}</span><small>${c.assets[d.id]?.status==='reviewed'?'Reviewed ✓':c.assets[d.id]?'Draft saved':'Ready to draft'}</small></button>`).join('')}</div></aside><section class="cb-editor">${active?`<div class="cb-editor-head"><div><div class="eyebrow">${E(CB.components.find(x=>x.id===active.type)?.label)}</div><h3>${E(CB.syncWeeks(c)[active.week-1]?.title)}</h3><p>${E(active.label)} · ${cbDate(CB.date(c.profile.launchDate,active.offset))}</p></div>${a?cbButton('regenerate','Regenerate','btn small',`data-id="${active.id}"`):''}</div>${a?`${a.signature&&a.signature!==CB.fingerprint(c,active)?'<div class="cb-callout"><strong>The blueprint has changed.</strong><p>Review this resource against the current teaching plan, or regenerate it. Your existing wording has been preserved.</p></div>':''}<div class="formgrid cb-editor-meta">${cbField(c,'assets.'+active.id+'.owner','Resource owner',{placeholder:active.owner+' lead'})}${cbField(c,'assets.'+active.id+'.reviewer','Reviewer',{placeholder:'Name'})}${cbField(c,'assets.'+active.id+'.status','Editorial status',{type:'select',options:[['draft','Drafting'],['review','Ready for review'],['reviewed','Reviewed']]})}<div class="field"><span>Keep a separate copy</span>${cbButton('export-asset','Download this resource','btn small',`data-id="${active.id}"`)}</div></div><label class="field cb-body-field"><span>Editable resource draft</span><textarea id="cb-resource-body" data-cb-field="assets.${active.id}.body" rows="24" maxlength="60000" spellcheck="true">${E(a.body)}</textarea></label><p class="cb-helper">Changes save automatically on this device. Regenerating replaces this draft after confirmation; editing the blueprint does not replace your work.</p>`:cbEmpty('Ready when you are','Create this resource from the weekly teaching plan and its connected sources.',cbButton('build-one','Create this draft','btn primary',`data-id="${active.id}"`))}`:''}</section></div>`}`;
}
function cbLaunch(c){const tasks=CB.launchTasks(c),cap=CB.capacity(c),hasDate=!!c.profile.launchDate;return cbHeader('06 / Launch','Give your team a clear path to launch','Dates follow your opening gathering. Assign owners, track preparation, and plan your capacity.',cbButton('export-calendar','Download calendar','btn',!hasDate?'disabled':''))+`<div class="cb-panel"><div class="formgrid">${cbField(c,'profile.launchDate','Opening gathering / launch date',{type:'date'})}<div class="field"><span>Campaign ends</span><div class="cb-date-display">${hasDate?cbDate(CB.date(c.profile.launchDate,c.profile.duration-1)):'Choose a launch date'}</div></div></div><p class="cb-helper">Preparation starts eight weeks before launch. If your date is closer, adjust responsibilities and scope with your team.</p></div>
  <details class="cb-panel" open><summary>Plan for people, groups, and print</summary><div class="formgrid cb-space">${cbField(c,'profile.attendance','Expected adult attendance',{type:'number',max:100000})}${cbField(c,'profile.participation','Participation target (%)',{type:'number',max:100})}${cbField(c,'profile.groupSize','People per group',{type:'number',min:1,max:100})}${cbField(c,'profile.existingGroups','Existing groups participating',{type:'number',max:10000})}${cbField(c,'profile.printBuffer','Extra printed copies (%)',{type:'number',max:100})}</div><div class="cb-capacity">${[[cap.participants,'participants'],[cap.groups,'groups needed'],[cap.newHosts,'additional hosts'],[cap.copies,'printed copies']].map(([n,label])=>`<div><strong>${c.profile.attendance?fmt(n):'—'}</strong><span>${label}</span></div>`).join('')}</div><p class="cb-helper">Calculated from your assumptions. Group and host counts round up; print copies include your chosen buffer.</p></details>
  <div class="cb-panel"><div class="cb-section-heading"><div><h3>One owner for every next step</h3><p>${tasks.filter(t=>t.done).length} of ${tasks.length} tasks complete</p></div>${cbButton('export-tasks','Download task list','btn small')}</div><div class="cb-assign-all"><label class="field"><span>Assign all currently unassigned tasks to</span><input id="cb-default-owner" placeholder="Campaign coordinator’s name" maxlength="200"></label>${cbButton('assign-owner','Assign owner','btn')}</div></div>
  <div class="cb-launch-phases">${CB.phases.map((phase,i)=>{const list=tasks.filter(t=>t.phase===phase.id);return `<section class="cb-phase"><div class="cb-phase-head"><span>${String(i+1).padStart(2,'0')}</span><div><h3>${phase.label}</h3><p>${phase.description}</p></div></div><div class="cb-task-list">${list.map(t=>`<div class="cb-task ${t.done?'done':''}"><label class="cb-check"><input type="checkbox" data-cb-task="${t.id}" data-property="done" ${t.done?'checked':''}><span><strong>${E(t.title)}</strong><small>${t.date?cbDate(t.date):(t.offset<0?Math.abs(t.offset)+' days before launch':t.offset===0?'Launch day':t.offset+' days after launch')} · ${E(t.role)}</small></span></label><label class="field"><span class="sr-only">Owner for ${E(t.title)}</span><input aria-label="Owner for ${E(t.title)}" data-cb-task="${t.id}" data-property="owner" maxlength="200" value="${E(t.owner)}" placeholder="Assign an owner"></label></div>`).join('')}</div></section>`;}).join('')}</div>`;}
function cbReview(c){const checks=CB.readiness(c),done=checks.filter(x=>x.done).length;return cbHeader('07 / Review & export','Bring the whole campaign together','Review what is ready, name what remains, and give your team a usable playbook.')+`<div class="cb-panel cb-accent"><div class="cb-section-heading"><div><div class="eyebrow">Readiness</div><h3>${done===checks.length?'Your planning checklist is complete':done+' of '+checks.length+' readiness steps complete'}</h3><p>You can export a working draft at any time. The playbook retains its review and source status.</p></div><span class="cb-readiness-number">${Math.round(done/checks.length*100)}<small>%</small></span></div><div class="cb-readiness-list">${checks.map(x=>`<a href="#/campaigns/${c.id}?step=${cbSteps[x.step][0]}" class="${x.done?'complete':''}"><span class="cb-readiness-check">${x.done?'✓':icon('arrow')}</span><span>${x.label}</span><small>${x.done?'Done':'Review →'}</small></a>`).join('')}</div></div>
  <div class="cb-panel"><h3>Record what your team is learning</h3><p class="cb-helper">These are actual observations you enter, separate from the capacity targets.</p><div class="formgrid">${[['participants','Participants'],['groups','Groups meeting'],['hosts','Active hosts'],['stories','Stories received'],['nextSteps','People taking a next step']].map(([key,label])=>cbField(c,'measures.'+key,label,{type:'number',max:1000000})).join('')}${cbField(c,'measures.baseline','Entry reflection / starting point',{type:'textarea',full:true,placeholder:'What did people report before the campaign?'})}${cbField(c,'measures.reflection','What changed, and what should continue?',{type:'textarea',full:true,placeholder:'Record observed practices, feedback, and next steps.'})}</div></div>
  <div class="cb-panel"><h3>Final pastoral review</h3><div class="formgrid">${cbField(c,'review.pastor','Pastoral reviewer')}${cbField(c,'review.date','Review date',{type:'date'})}</div><div class="cb-space">${cbCheck('review.approved','The campaign has received my pastoral review for the intended audience and use.',c.review.approved)}</div><p class="cb-helper">This records your review; it does not publish or send the campaign. Further edits reopen this review.</p></div>
  <div class="cb-export-grid"><article class="cb-export-card"><span class="cb-source-badge lifetogether">For your team</span><h3>Campaign playbook</h3><p>The vision, sources, weekly plan, daily rhythm, launch tasks, and resource drafts in one printable document.</p>${cbButton('export-html','Download playbook','btn primary')}${cbButton('export-markdown','Download as Markdown','btn flat small')}</article><article class="cb-export-card"><span class="cb-source-badge pastor">For your next session</span><h3>Editable campaign backup</h3><p>A complete campaign file, including your sermon notes and edits. Import it on another device to continue.</p>${cbButton('backup','Download campaign backup','btn primary')}<p class="cb-helper">Contains the source material you added. Share with your intended team.</p></article></div><div class="cb-export-tools">${cbButton('export-calendar','Calendar (.ics)','btn',!c.profile.launchDate?'disabled':'')}${cbButton('export-tasks','Launch tasks (.csv)','btn')}${cbButton('export-sources','Source inventory (.csv)','btn')}</div>`;
}
function cbFilename(c,suffix){return (c.title||'LifeTogether-Campaign').replace(/[^a-zA-Z0-9 -]/g,'').trim().replace(/\s+/g,'-').slice(0,80)+suffix;}
function cbHTML(c){const lines=CB.markdown(c).split('\n'),html=lines.map(line=>/^### /.test(line)?'<h3>'+E(line.slice(4))+'</h3>':/^## /.test(line)?'<h2>'+E(line.slice(3))+'</h2>':/^# /.test(line)?'<h1>'+E(line.slice(2))+'</h1>':line==='---'?'<hr>':line?'<p>'+E(line)+'</p>':'').join('\n');return `<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>${E(c.title)} — Campaign playbook</title><style>body{font:16px/1.65 Georgia,serif;color:#173747;background:#f5f5f0;margin:0}main{max-width:850px;margin:30px auto;background:white;padding:50px}h1{font-size:42px;line-height:1.15}h2{font-size:25px;border-top:2px solid #d9e3df;padding-top:30px;margin-top:48px}h3{font-size:20px;margin-top:30px;color:#17685c}p{white-space:pre-wrap;margin:8px 0;overflow-wrap:anywhere}small,button{font:14px system-ui}button{background:#17685c;color:white;border:0;padding:12px 20px;border-radius:5px;cursor:pointer}hr{border:0;border-top:1px solid #d9e3df;margin:40px 0}@media(max-width:700px){main{padding:24px;margin:0}h1{font-size:32px}}@media print{body{background:white}main{padding:0;margin:0;max-width:none}button{display:none}h2,h3{break-after:avoid}p{orphans:3;widows:3}}</style><main><small>LIFETOGETHER / CAMPAIGN BUILDER</small><p><button onclick="window.print()">Print / save PDF</button></p>${html}</main></html>`;}
function cbDownload(c,kind){const name=cbFilename(c,'');switch(kind){case 'backup':download(name+'.campaign.json',JSON.stringify(c,null,2),'application/json');break;case 'export-html':download(name+'-Playbook.html',cbHTML(c),'text/html;charset=utf-8');break;case 'export-markdown':download(name+'-Playbook.md',CB.markdown(c),'text/markdown;charset=utf-8');break;case 'export-calendar':download(name+'-Launch.ics',CB.calendar(c),'text/calendar;charset=utf-8');break;case 'export-tasks':download(name+'-Tasks.csv',LTCore.csv([['Phase','Task','Date','Days from launch','Owner','Complete'],...CB.launchTasks(c).map(t=>[t.phase,t.title,t.date,t.offset,t.owner,t.done?'Yes':'No'])]),'text/csv;charset=utf-8');break;case 'export-sources':download(name+'-Sources.csv',LTCore.csv([['Library','Title','Subtitle','Speaker','Church','Scripture','Link','Location','Permission','Selected','Catalog ID'],...c.sources.map(s=>[CB.layers[s.layer],s.title,s.subtitle,s.speaker,s.church,s.scripture,s.url,s.locator,s.permission,s.selected?'Yes':'No',s.recordId])]),'text/csv;charset=utf-8');break;}}
function cbRender(){campaignsPage();}
function campaignClick(e){const el=e.target.closest('[data-cb]');if(!el?.dataset?.cb)return false;const c=cbCurrent(),action=el.dataset.cb;e.preventDefault();try{
  if(action==='new'){cbStart(el.dataset.id);return true;}
  if(action==='example'){if(cbWorkspace.campaigns.length>=25)throw Error('Back up and archive a campaign before adding another.');const example=CB.example();cbWorkspace.campaigns.unshift(example);cbOpen(example);return true;}
  if(action==='duplicate'){const old=cbWorkspace.campaigns.find(x=>x.id===el.dataset.id);if(old){if(cbWorkspace.campaigns.length>=25)throw Error('Back up and archive a campaign before adding another.');const next=CB.importCampaign(old);next.title=old.title+' — copy';next.review.approved=false;cbWorkspace.campaigns.unshift(next);cbOpen(next);}return true;}
  if(action==='delete'){const old=cbWorkspace.campaigns.find(x=>x.id===el.dataset.id);if(old&&confirm('Download a backup before removing this campaign from this device. A backup will download now; continue?')){cbDownload(old,'backup');cbWorkspace.campaigns=cbWorkspace.campaigns.filter(x=>x.id!==old.id);cbPersist(true);cbDashboard();}return true;}
  if(!c)return true;
  if(['backup','export-html','export-markdown','export-calendar','export-tasks','export-sources'].includes(action)){cbDownload(c,action);return true;}
  switch(action){
    case 'suggest-objective':c.profile.objective=CB.goals[c.profile.goal].promise;break;
    case 'layer':cbUI.layer=el.dataset.layer;cbUI.query='';cbUI.page=1;cbUI.newSource=false;cbUI.sourceEdit='';break;
    case 'search':cbUI.query=$('#cb-source-search')?.value||'';cbUI.page=1;break;
    case 'source-page':cbUI.page=Number(el.dataset.page)||1;break;
    case 'add-source':cbUI.newSource=true;cbUI.sourceEdit='';break;
    case 'close-source':cbUI.newSource=false;cbUI.sourceEdit='';break;
    case 'edit-source':cbUI.sourceEdit=el.dataset.id;cbUI.newSource=false;break;
    case 'add-record':{const r=byId.get(el.dataset.id);if(r&&CB.catalogLayer(r)&&!c.sources.some(s=>s.recordId===r['Master ID'])){if(c.sources.length>=200)throw Error('Use up to 200 sources in one campaign.');c.sources.push(CB.fromRecord(r));toast('Source added. Attach notes when you are ready.');}break;}
    case 'remove-source':{const s=c.sources.find(x=>x.id===el.dataset.id);if(s&&confirm('Remove “'+s.title+'” from this campaign? Existing resource drafts will be kept.')){c.sources=c.sources.filter(x=>x.id!==s.id);c.weeks.forEach(w=>{if(w.sourceIds.includes(s.id)){w.sourceIds=w.sourceIds.filter(x=>x!==s.id);w.reviewed=false;}});}break;}
    case 'source-template':download('Sermon-Library-Import-Template.csv',LTCore.csv([['Title','Subtitle','Speaker','Church','Series','Date','Scripture','Big idea','Practice','Notes','URL','Locator']]),'text/csv;charset=utf-8');return true;
    case 'preset-pilot':case 'preset-church':case 'preset-full':{const pilot=['sermons','groups','daily','next'],church=['sermons','groups','daily','family','children','youth','hosts','prayer','testimony','email','assessment','next'];CB.components.forEach(x=>c.scope[x.id]=action==='preset-full'||(action==='preset-pilot'?pilot:church).includes(x.id)?'now':'later');break;}
    case 'assign-sources':{const ss=CB.teachingSources(c);if(!ss.length){toast('Select a teaching source first.');return true;}CB.syncWeeks(c).forEach((w,i)=>{if(!w.sourceIds.length){w.sourceIds=[ss[i%ss.length].id];w.reviewed=false;w.edited=true;}});toast('Empty weeks connected. Use teaching notes to adapt the weekly ideas.');break;}
    case 'use-source-teaching':{const w=c.weeks[Number(el.dataset.week)],s=c.sources.find(x=>x.id===el.dataset.id);if(!w||!s)return true;if(s.catalogRestricted||(s.layer==='church'&&!['owned','authorized'].includes(s.permission))){toast('Confirm adaptation permission before using global teaching notes.');return true;}if(confirm('Replace this week’s matching big idea, Scripture, and practice with the supplied source notes?')){const x=CB.extracted(s);for(const k of ['bigIdea','scripture','practice'])if(x[k])w[k]=x[k];if(x.scripture)w.scriptureSuggested=false;if(!w.sourceIds.includes(s.id))w.sourceIds.push(s.id);w.reviewed=false;w.edited=true;cbUI.week=w.number;}break;}
    case 'build-assets':CB.buildAssets(c);toast('Missing drafts created. Existing edits preserved.');break;
    case 'build-one':{const d=CB.descriptors(c).find(x=>x.id===el.dataset.id);if(d&&!c.assets[d.id])c.assets[d.id]={body:CB.draft(c,d),signature:CB.fingerprint(c,d),status:'draft',owner:'',reviewer:'',edited:false};break;}
    case 'asset':cbUI.asset=el.dataset.id;break;
    case 'regenerate':{const d=CB.descriptors(c).find(x=>x.id===el.dataset.id);if(d&&confirm('Replace this resource draft with a fresh version from the current blueprint? Download the resource first if you want to keep your current wording.'))c.assets[d.id]={...c.assets[d.id],body:CB.draft(c,d),signature:CB.fingerprint(c,d),status:'draft',edited:false};break;}
    case 'export-asset':{const d=CB.descriptors(c).find(x=>x.id===el.dataset.id),a=c.assets[el.dataset.id];if(d&&a)download(cbFilename(c,'-'+d.id+'.txt'),a.body,'text/plain;charset=utf-8');return true;}
    case 'assign-owner':{const owner=$('#cb-default-owner')?.value.trim();if(!owner){toast('Enter a coordinator’s name first.');return true;}CB.launchTasks(c).forEach(t=>{if(!t.owner)c.tasks[t.id]={...c.tasks[t.id],owner};});break;}
  }
  if(!['layer','search','source-page','add-source','close-source','edit-source','asset'].includes(action))cbTouch(c);cbRender();
 }catch(err){toast(err.message);}return true;
}
function campaignInput(e){const el=e.target,c=cbCurrent();if(!c)return false;if(el.dataset.cbSearch)return true;if(el.dataset.cbTask&&el.dataset.property==='owner'){c.tasks[el.dataset.cbTask]={...c.tasks[el.dataset.cbTask],owner:el.value};cbTouch(c);return true;}if(!el.dataset.cbField)return false;const path=el.dataset.cbField;if(el.type==='checkbox'||el.tagName==='SELECT'||el.type==='date')return true;let v=el.type==='number'?(el.value===''?'':CB.number(el.value,Number(el.min)||0,Number(el.max)||1000000)):el.value;cbSet(c,path,v);if(path.startsWith('assets.')&&path.endsWith('.body')){const key=path.split('.')[1];c.assets[key].edited=true;c.assets[key].status='draft';const status=$('#cb-assets-'+key+'-status');if(status)status.value='draft';}if(path.startsWith('weeks.')){const w=c.weeks[Number(path.split('.')[1])];w.reviewed=false;w.edited=true;}cbTouch(c);return true;}
async function cbReadDOCX(file){const text=await CB.docxXML(new Uint8Array(await file.arrayBuffer()));const xml=new DOMParser().parseFromString(text,'application/xml');if(xml.querySelector('parsererror'))throw Error('Word document text is malformed.');return [...xml.getElementsByTagName('w:p')].map(p=>[...p.getElementsByTagName('w:t')].map(t=>t.textContent).join('')).join('\n');}
async function campaignChange(e){const el=e.target,c=cbCurrent();
 if(el.id==='cb-import-campaign'){try{const f=el.files?.[0];if(!f)return true;if(f.size>3500000)throw Error('Use a campaign backup smaller than 3.5 MB.');if(cbWorkspace.campaigns.length>=25)throw Error('Back up and archive a campaign before importing another.');const imported=CB.importCampaign(JSON.parse(await f.text()));cbWorkspace.campaigns.unshift(imported);cbOpen(imported);toast('Campaign imported as a new local copy.');}catch(err){toast(err.message);}return true;}
 if(!c)return false;
 if(el.id==='cb-import-sources'){try{const files=[...el.files];if(!files.length)return true;const added=[];for(const file of files){if(file.size>2000000)throw Error('Each file must be under 2 MB. Split a large sermon archive into smaller files.');const text=/\.docx$/i.test(file.name)?await cbReadDOCX(file):await file.text();const imported=CB.importSources(text,file.name,cbUI.layer);if(!imported.length)throw Error('No titled sermons found in '+file.name+'.');added.push(...imported);}if(c.sources.length+added.length>200)throw Error('Use up to 200 sources in one campaign.');c.sources.push(...added);cbTouch(c);cbRender();toast(added.length+' sources imported on this device.');}catch(err){toast(err.message);}return true;}
 if(el.id==='cb-resource-type'){cbUI.type=el.value;cbUI.asset='';cbRender();return true;}
 if(el.dataset.cbSelectSource){const s=c.sources.find(x=>x.id===el.dataset.cbSelectSource);if(s)s.selected=el.checked;cbTouch(c);cbRender();return true;}
 if(el.dataset.cbWeekSource!==undefined){const w=c.weeks[Number(el.dataset.cbWeekSource)];if(w){w.sourceIds=el.checked?[...new Set([...w.sourceIds,el.dataset.id])]:w.sourceIds.filter(x=>x!==el.dataset.id);w.reviewed=false;w.edited=true;cbUI.week=w.number;}cbTouch(c);cbRender();return true;}
 if(el.dataset.cbTask){c.tasks[el.dataset.cbTask]={...c.tasks[el.dataset.cbTask],[el.dataset.property]:el.type==='checkbox'?el.checked:el.value};cbTouch(c);if(el.type==='checkbox')cbRender();return true;}
 if(!el.dataset.cbField)return false;const path=el.dataset.cbField;
 if(el.type==='checkbox'||el.tagName==='SELECT'||el.type==='date'){let v=el.type==='checkbox'?el.checked:el.value;if(path==='profile.duration')v=Number(v);cbSet(c,path,v);if(path.startsWith('weeks.')){cbUI.week=Number(path.split('.')[1])+1;c.weeks[Number(path.split('.')[1])].edited=true;}if(path.startsWith('assets.')&&path.endsWith('.status')&&v==='reviewed'&&!c.assets[path.split('.')[1]].body.trim()){c.assets[path.split('.')[1]].status='draft';toast('Add resource content before marking it reviewed.');}if(path.startsWith('assets.')&&path.endsWith('.status')&&v==='reviewed'){const d=CB.descriptors(c).find(x=>x.id===path.split('.')[1]);if(d)c.assets[d.id].signature=CB.fingerprint(c,d);}if(path==='review.approved'){c.updatedAt=new Date().toISOString();cbPersist();}else cbTouch(c);cbRender();}
 else if(el.type==='number'){campaignInput(e);cbRender();}
 else if(path.startsWith('weeks.')){cbUI.week=Number(path.split('.')[1])+1;}
 return true;
}
function campaignSubmit(e){if(e.target.id!=='cb-source-form')return false;e.preventDefault();const c=cbCurrent();if(!c)return true;try{const fields=Object.fromEntries(new FormData(e.target)),existing=c.sources.find(s=>s.id===fields.sourceId),s=CB.source({...existing,...fields,id:fields.sourceId||CB.id(),selected:existing?existing.selected:true,complete:fields.complete==='on'});if(!s.title.trim())throw Error('Add the sermon or resource title.');if(!existing&&c.sources.length>=200)throw Error('Use up to 200 sources in one campaign.');if(fields.url&&!CB.safeURL(fields.url))throw Error('Use a complete http or https source link.');if(existing)c.sources[c.sources.indexOf(existing)]=s;else c.sources.push(s);c.weeks.filter(w=>w.sourceIds.includes(s.id)).forEach(w=>w.reviewed=false);cbUI.layer=s.layer;cbUI.newSource=false;cbUI.sourceEdit='';cbTouch(c);cbRender();toast('Source saved with its teaching notes.');}catch(err){toast(err.message);}return true;}
