function wsChurch(){const c=wsState.church;shell(heading('Your church profile','Set your church’s context once. New campaigns and journey profiles can begin with it.')+'<form id="ws-church" class="ws-panel"><div class="formgrid">'+wsField('church','Church name',c.church,{required:true})+wsField('pastor','Lead pastor / teaching voice',c.pastor)+wsField('mission','Mission and values',c.mission,{area:true,full:true,maxlength:4000})+wsField('context','Our church right now',c.context,{area:true,full:true,maxlength:4000})+wsField('theology','Theological convictions',c.theology,{area:true,full:true,maxlength:4000})+wsField('voice','Teaching voice',c.voice,{area:true,full:true,maxlength:4000})+wsField('goal','Primary formation focus',c.goal||'community',{options:Object.entries(CB.goals).map(([id,g])=>[id,g.label])})+wsField('duration','Usual campaign length',c.duration||40,{options:CB.durations.map(n=>[n,n+' days'])})+wsField('translation','Scripture translation',c.translation||'NIV',{options:['NIV','ESV','NLT','CSB','NKJV','KJV','NRSVUE','Other — record in theological notes']})+wsField('attendance','Expected adult attendance',c.attendance||0,{type:'number'})+wsField('existingGroups','Existing groups',c.existingGroups||0,{type:'number'})+wsField('groupSize','Usual people per group',c.groupSize||10,{type:'number'})+'</div><div class="formactions"><button class="btn primary" type="submit">Save church profile</button>'+wsButton('church-survey','Use in Journey finder')+'</div><p class="inline-note">New campaigns use this profile automatically. Existing campaigns keep their own edits; use “Apply church profile” in Vision when needed. Saved on this device.</p></form>','church','Church profile');}
